@startuml

class UnderAgedUser {
  + fullName : string
  + studentCard : string
}

class AdultUser {
  + fullName : string
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowingHistory {
  + date : date
}

UnderAgedUser "0..1" -- "*" BorrowingHistory : has
AdultUser "0..1" -- "*" BorrowingHistory : has
BorrowingHistory "*" -- "1" Book : involves

UnderAgedUser "0..4" -- "0..4" Book : borrows
AdultUser "0..4" -- "0..4" Book : borrows

@enduml

